const workflowContext = this;
const env = $env || {};

const headers = ($json && $json.headers) ? $json.headers : {};
const body = ($json && $json.body) ? $json.body : ($json ?? {});

function required(value, name) {
  if (value === undefined || value === null || String(value).trim() === '') {
    throw new Error(`${name} is required`);
  }
  return value;
}

function trimSlash(value) {
  return String(value || '').replace(/\/+$/, '');
}

function safeString(value) {
  if (value === undefined || value === null) return '';
  return String(value).trim();
}

function isTruthy(value) {
  if (value === undefined || value === null) return false;
  const v = String(value).toLowerCase();
  return ['1', 'true', 'yes', 'y', 'on'].includes(v);
}

function yyyymm(d) {
  const dt = (d instanceof Date) ? d : new Date(d);
  const y = dt.getUTCFullYear();
  const m = String(dt.getUTCMonth() + 1).padStart(2, '0');
  return `${y}-${m}`;
}

function previousMonthYyyymm(now = new Date()) {
  const d = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 1, 0, 0, 0));
  d.setUTCMonth(d.getUTCMonth() - 1);
  return yyyymm(d);
}

function parseYamlValue(text, key) {
  const m = String(text || '').match(new RegExp(`^${key}:\\s*(.*)$`, 'm'));
  if (!m) return '';
  const raw = String(m[1] || '').trim();
  if (!raw) return '';
  if (raw.startsWith('"') && raw.endsWith('"')) return raw.slice(1, -1).replace(/\\"/g, '"');
  if (raw.startsWith("'") && raw.endsWith("'")) return raw.slice(1, -1);
  return raw;
}

function mdEscape(value) {
  return String(value || '').replace(/\|/g, '\\|');
}

const realm = safeString(body.realm || env.N8N_REALM || env.N8N_OBSERVER_REALM || 'default') || 'default';

const gitlabBaseUrl = trimSlash(
  body.gitlab_base_url ||
  body.GITLAB_BASE_URL ||
  env.N8N_GITLAB_BASE_URL ||
  env.GITLAB_BASE_URL ||
  env.GITLAB_URL ||
  env.SERVICE_URL_GITLAB ||
  ''
);

const gitlabApiBase = trimSlash(
  body.gitlab_api_base_url ||
  body.GITLAB_API_BASE_URL ||
  env.N8N_GITLAB_API_BASE_URL ||
  env.GITLAB_API_BASE_URL ||
  (gitlabBaseUrl ? `${gitlabBaseUrl}/api/v4` : '') ||
  ''
);

const gitlabToken = safeString(env.N8N_GITLAB_TOKEN || env.GITLAB_TOKEN || env.GITLAB_ADMIN_TOKEN || '');

function normalizeProjectRef(value) {
  const v = safeString(value);
  if (!v) return '';
  if (/^\d+$/.test(v)) return v;
  if (v.includes('/')) return v;
  return `${realm}/${v}`;
}

let projectRefRaw = safeString(
  body.HR_TALENT_GITLAB_PROJECT_ID ||
  body.HR_TALENT_GITLAB_PROJECT_PATH ||
  body.HR_TALENT_PROJECT_PATH ||
  body.HR_TALENT_MANAGEMENT_PROJECT_PATH ||
  env.HR_TALENT_GITLAB_PROJECT_ID ||
  env.HR_TALENT_GITLAB_PROJECT_PATH ||
  env.HR_TALENT_PROJECT_PATH ||
  env.HR_TALENT_MANAGEMENT_PROJECT_PATH ||
  env.N8N_GITLAB_PROJECT_ID ||
  env.N8N_GITLAB_PROJECT_PATH ||
  ''
);

let projectRef = normalizeProjectRef(projectRefRaw);
if (!projectRef) {
  projectRef = `${realm}/hr-talent-management`;
}
const defaultBranch = safeString(env.HR_TALENT_DEFAULT_BRANCH || 'main') || 'main';

const targetMonth = safeString(body.month || body.yyyymm || body.target_month || '') || previousMonthYyyymm(new Date());
if (!/^\d{4}-\d{2}$/.test(targetMonth)) {
  throw new Error('month must be in YYYY-MM format');
}

const dryRun = isTruthy(body.dry_run || body.dryRun || false);

required(gitlabApiBase, 'GITLAB_API_BASE_URL');
required(gitlabToken, 'GITLAB_TOKEN');
required(projectRef, 'HR_TALENT_GITLAB_PROJECT_ID or HR_TALENT_GITLAB_PROJECT_PATH (or HR_TALENT_PROJECT_PATH)');

const zulipBaseUrl = trimSlash(env.ZULIP_API_BASE_URL || env.N8N_ZULIP_API_BASE_URL || '');
const zulipEmail = safeString(env.ZULIP_BOT_EMAIL || env.ZULIP_EMAIL || '');
const zulipApiKey = safeString(env.ZULIP_BOT_API_KEY || env.ZULIP_API_KEY || '');
const zulipStream = safeString(env.HR_TALENT_ZULIP_STREAM || '');
const zulipTopicDefault = safeString(env.HR_TALENT_ZULIP_TOPIC || 'hr-talent') || 'hr-talent';

async function zulipSendStreamMessage(content, topic) {
  if (!zulipBaseUrl || !zulipEmail || !zulipApiKey || !zulipStream) return null;
  const url = `${zulipBaseUrl}/api/v1/messages`;
  const auth = Buffer.from(`${zulipEmail}:${zulipApiKey}`).toString('base64');
  return await workflowContext.helpers.httpRequest({
    method: 'POST',
    url,
    json: true,
    headers: {
      'Authorization': `Basic ${auth}`,
    },
    form: {
      type: 'stream',
      to: zulipStream,
      topic: topic || zulipTopicDefault,
      content,
    }
  });
}


const projectEncoded = encodeURIComponent(projectRef);

async function listTree(path) {
  const out = [];
  let page = 1;
  while (page <= 50) {
    const url = `${gitlabApiBase}/projects/${projectEncoded}/repository/tree`;
    const items = await workflowContext.helpers.httpRequest({
      method: 'GET',
      url,
      json: true,
      headers: { 'PRIVATE-TOKEN': gitlabToken },
      qs: {
        path,
        recursive: true,
        per_page: 100,
        page
      }
    });
    if (!Array.isArray(items) || items.length === 0) break;
    out.push(...items);
    if (items.length < 100) break;
    page += 1;
  }
  return out;
}

async function getFileRaw(filePath, ref) {
  const url = `${gitlabApiBase}/projects/${projectEncoded}/repository/files/${encodeURIComponent(filePath)}/raw`;
  return await workflowContext.helpers.httpRequest({
    method: 'GET',
    url,
    headers: { 'PRIVATE-TOKEN': gitlabToken },
    qs: { ref },
    json: false
  });
}

async function createBranch(branch) {
  const url = `${gitlabApiBase}/projects/${projectEncoded}/repository/branches`;
  try {
    return await workflowContext.helpers.httpRequest({
      method: 'POST',
      url,
      json: true,
      headers: { 'PRIVATE-TOKEN': gitlabToken },
      qs: { branch, ref: defaultBranch }
    });
  } catch (err) {
    const status = err?.response?.statusCode || err?.statusCode || null;
    if (status === 400 || status === 409) return null;
    throw err;
  }
}

async function fileExists(filePath, ref) {
  const url = `${gitlabApiBase}/projects/${projectEncoded}/repository/files/${encodeURIComponent(filePath)}`;
  try {
    await workflowContext.helpers.httpRequest({
      method: 'GET',
      url,
      json: true,
      headers: { 'PRIVATE-TOKEN': gitlabToken },
      qs: { ref }
    });
    return true;
  } catch (err) {
    const status = err?.response?.statusCode || err?.statusCode || null;
    if (status === 404) return false;
    return false;
  }
}

async function commitFile(branch, filePath, content, commitMessage, action) {
  const url = `${gitlabApiBase}/projects/${projectEncoded}/repository/commits`;
  return await workflowContext.helpers.httpRequest({
    method: 'POST',
    url,
    json: true,
    headers: { 'PRIVATE-TOKEN': gitlabToken },
    body: {
      branch,
      commit_message: commitMessage,
      actions: [
        {
          action,
          file_path: filePath,
          content,
        }
      ]
    }
  });
}

async function createMr(sourceBranch, title, description) {
  const url = `${gitlabApiBase}/projects/${projectEncoded}/merge_requests`;
  return await workflowContext.helpers.httpRequest({
    method: 'POST',
    url,
    json: true,
    headers: { 'PRIVATE-TOKEN': gitlabToken },
    body: {
      source_branch: sourceBranch,
      target_branch: defaultBranch,
      title,
      description,
      remove_source_branch: true,
    }
  });
}

let tree;
try {
  tree = await listTree('ledger/skill_updates');
} catch (err) {
  const status = err?.response?.statusCode || err?.statusCode || err?.httpCode || null;
  const responseBody = err?.response?.body || err?.response?.data || null;
  return [{
    json: {
      ok: false,
      status_code: status || 500,
      error: String(err?.message || err),
      response_body: responseBody,
      realm,
      project_ref: projectRef,
      month: targetMonth,
    }
  }];
}

const ymlFiles = (Array.isArray(tree) ? tree : [])
  .filter((i) => i && i.type === 'blob')
  .map((i) => String(i.path || ''))
  .filter((p) => p.endsWith('.yml') || p.endsWith('.yaml'));

const rows = [];
const skillCount = {};
const peopleSet = new Set();

for (const p of ymlFiles) {
  let raw;
  try {
    raw = await getFileRaw(p, defaultBranch);
  } catch (err) {
    continue;
  }
  const requestedAt = parseYamlValue(raw, 'requested_at');
  const personKey = parseYamlValue(raw, 'person_key');
  const skillId = parseYamlValue(raw, 'skill_id');
  const level = parseYamlValue(raw, 'level');

  const month = requestedAt ? String(requestedAt).slice(0, 7) : '';
  if (month !== targetMonth) continue;

  rows.push({
    file: p,
    requested_at: requestedAt,
    person_key: personKey,
    skill_id: skillId,
    level,
  });
  if (personKey) peopleSet.add(personKey);
  if (skillId) skillCount[skillId] = (skillCount[skillId] || 0) + 1;
}

const total = rows.length;
const uniquePeople = peopleSet.size;
const uniqueSkills = Object.keys(skillCount).length;
const topSkills = Object.entries(skillCount)
  .sort((a, b) => (b[1] - a[1]) || a[0].localeCompare(b[0]))
  .slice(0, 20);

const nowIso = new Date().toISOString();

const reportMd = [
  `# HR Talent 月次レポート (${targetMonth})`,
  '',
  `- realm: ${realm}`,
  `- generated_at: ${nowIso}`,
  '',
  '## サマリ',
  '',
  `- スキル更新（skill_updates）件数: **${total}**`,
  `- 対象者（ユニーク）: **${uniquePeople}**`,
  `- 更新スキル種別（ユニーク）: **${uniqueSkills}**`,
  '',
  '## スキル別 件数（上位）',
  '',
  '| skill_id | count |',
  '|---|---:|',
  ...topSkills.map(([skill, count]) => `| ${mdEscape(skill)} | ${count} |`),
  '',
  '## 明細（当月の skill_update レジャー）',
  '',
  '| requested_at | person_key | skill_id | level | file |',
  '|---|---|---|---|---|',
  ...rows
    .sort((a, b) => String(a.requested_at || '').localeCompare(String(b.requested_at || '')))
    .map((r) => `| ${mdEscape(r.requested_at)} | ${mdEscape(r.person_key)} | ${mdEscape(r.skill_id)} | ${mdEscape(r.level)} | ${mdEscape(r.file)} |`),
  '',
  '---',
  'このレポートは `ledger/skill_updates/*.yml`（requested_at の YYYY-MM）を集計して生成。',
].join('\n');

if (dryRun) {
  return [{
    json: {
      ok: true,
      status_code: 200,
      dry_run: true,
      realm,
      project_ref: projectRef,
      month: targetMonth,
      counts: { total, unique_people: uniquePeople, unique_skills: uniqueSkills },
      report_path: `reports/monthly/${targetMonth}.md`,
      report_markdown: reportMd,
    }
  }];
}

const branch = `hr-monthly-report-${targetMonth}`;
const reportPath = `reports/monthly/${targetMonth}.md`;

try {
  await createBranch(branch);
  const exists = await fileExists(reportPath, branch);
  const action = exists ? 'update' : 'create';

  await commitFile(
    branch,
    reportPath,
    reportMd + '\n',
    `Add HR Talent monthly report (${targetMonth})`,
    action
  );

  const mr = await createMr(
    branch,
    `HR Talent monthly report (${targetMonth})`,
    `This MR was generated by n8n (hr-talent-monthly-report-generate-request).\n\nrealm: ${realm}\nmonth: ${targetMonth}`
  );


  try {
    const msg = [
      `HR Talent: 月次レポートMRを作成しました (${targetMonth})`,
      `- realm: ${realm}`,
      mr?.web_url ? `- mr: ${mr.web_url}` : null,
      `- report: ${reportPath}`,
    ].filter((v) => v !== null).join('\n');
    await zulipSendStreamMessage(msg, 'hr-monthly-report');
  } catch (err) {
    // ignore zulip failures
  }

  return [{
    json: {
      ok: true,
      status_code: 200,
      dry_run: false,
      realm,
      project_ref: projectRef,
      month: targetMonth,
      report_path: reportPath,
      mr_url: mr?.web_url || null,
      counts: { total, unique_people: uniquePeople, unique_skills: uniqueSkills },
    }
  }];
} catch (err) {
  const status = err?.response?.statusCode || err?.statusCode || err?.httpCode || null;
  const responseBody = err?.response?.body || err?.response?.data || null;
  return [{
    json: {
      ok: false,
      status_code: status || 500,
      error: String(err?.message || err),
      response_body: responseBody,
      realm,
      project_ref: projectRef,
      month: targetMonth,
      report_path: reportPath,
    }
  }];
}
